-- PR-UV-01
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-01'),
  'Este procedimiento inicia garantizando la disponibilidad de insumos (Jabón y Sanitas) en el stock de intendencia para la dotación oportuna en todas las áreas por el personal operativo, y finaliza cuando epidemiología supervisa que los insumos sean suficientes en cada área.',
  'Garantizar que en todos los servicios y durante todos los turnos, se cuente con los insumos (sanitas y jabón) suficientes para la realización de la higiene de manos.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Jefatura de Intendencia", "actividad": "Revisa diariamente la disponibilidad de insumos en el almacén de intendencia."}, {"num": "5.2", "responsable": "Jefatura de Intendencia", "actividad": "Solicita semanalmente al almacén general la cantidad necesaria de insumos para mantener el stock establecido a través de la Hoja de Requisición."}, {"num": "5.3", "responsable": "Jefatura de Intendencia", "actividad": "Entrega diariamente al personal operativo la cantidad ordinaria de sanitas y jabón a sus áreas durante su jornada."}, {"num": "5.4", "responsable": "Personal operativo de intendencia", "actividad": "El personal operativo coloca la cantidad ordinaria de sanitas y jabón a sus áreas durante su jornada."}, {"num": "5.5", "responsable": "Almacén", "actividad": "Surte cada semana el stock solicitado por la jefa de intendencia."}, {"num": "5.6", "responsable": "Personal operativo de intendencia", "actividad": "Recibe turno con llave de los despachadores de Sanitas y revisa la disponibilidad de insumos (jabón y sanitas)."}, {"num": "5.7", "responsable": "Personal operativo de intendencia", "actividad": "Pasa a todos los servicios como primera actividad de la jornada. Nota: En caso de que un área requiera de insumos, se deben surtir inmediatamente."}, {"num": "5.8", "responsable": "Personal operativo de intendencia", "actividad": "A mitad de su jornada, hará una nueva revisión en todos los servicios."}, {"num": "5.9", "responsable": "Personal operativo de intendencia", "actividad": "Al finalizar el turno, entregará al responsable del turno siguiente la llave de los despachadores e inicia su revisión de área."}, {"num": "5.10", "responsable": "UVEH", "actividad": "Supervisará a través de estudio de sombra y se registrará a través de la bitácora supervisión de centrales y áreas (FT-UV-22) en todas las áreas del Hospital para verificar que todas las áreas cuentan con los insumos suficientes. Nota: en caso de verificar que de manera continua no se tiene los insumos, se levantará incidencia interdepartamental, por incumplimiento del proceso."}]'::jsonb,
  '[{"riesgo": "Insuficiencia de Insumos en stock para Higiene de manos (Sanitas y Jabón).", "barrera": "Gestionar con la administración el abasto de insumos."}, {"riesgo": "No supervisión por parte del personal de intendencia de la falta de insumos.", "barrera": "Supervisión continua y concientización al personal de intendencia de la importancia de los insumos en las áreas."}]'::jsonb,
  '[{"nombre": "Guía de aplicación de la estrategia multimodal de la OMS, para la mejora de la higiene de manos (2010).", "codigo": "NA"}, {"nombre": "Norma oficial mexicana nom-045-ssa2-2015, para la vigilancia epidemiológica, prevención y control de las infecciones nosocomiales.", "codigo": "NA"}, {"nombre": "Supervisión de Centrales y Áreas", "codigo": "FT-UV-22"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/09/2023", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de Vigilancia Epidemiológica Hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Jefatura de Intendencia, Personal Operativo de Intendencia, Almacén y Unidad de Vigilancia Epidemiológica (UVEH)."}, {"tipo": "Supervisión", "descripcion": "Unidad de Vigilancia Epidemiológica Hospitalaria (UVEH)."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;


-- PR-UV-02
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-02'),
  'Este procedimiento inicia cuando el médico tratante ingresa al paciente y, finaliza admisión verifica que la habitación esté completa antes de realizar nuevo ingreso.',
  'Proporcionar habitaciones a nuestros pacientes, visitantes y colaboradores, de calidad y seguridad; mediante la correcta desinfección de las superficies hospitalarias y manejo adecuado de ropa limpia y sucia.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Médico tratante", "actividad": "Indica el ingreso."}, {"num": "5.2", "responsable": "Ama de Llaves", "actividad": "Realiza check list de la habitación."}, {"num": "5.3", "responsable": "Admisión", "actividad": "Realiza el trámite de ingreso administrativo y notifica a la Unidad de Vigilancia Epidemiológica Hospitalaria (UVEH), a través del censo diario electrónico del hospital."}, {"num": "5.4", "responsable": "UVEH", "actividad": "Valora, analiza y determina en base al diagnóstico del paciente, el tipo de aseo de superficies que requiere la habitación al momento de su egreso. Los Aseos consisten en Exhaustivos, Desinfección Ambiental (Nebulizado) y toma de Cultivo de habitación o cubículo (PR-IN-01 y PR-IN-02). Nota: El tipo de aseo se revalorará y modificará de acuerdo con la evolución de salud del paciente."}, {"num": "5.5", "responsable": "UVEH", "actividad": "Genera ''vales de control para la preparación de habitaciones y/o cubículos''."}, {"num": "5.6", "responsable": "Médico tratante", "actividad": "Indica el egreso del paciente. Notifica al personal de enfermería."}, {"num": "5.7", "responsable": "Enfermería", "actividad": "Informa al personal de admisión (conmutador), farmacia, administración y ama de llaves, del egreso del paciente. IT-JE-29 Egreso de paciente de habitación. Nota: sea paciente particular y/o aseguradora."}, {"num": "5.8", "responsable": "Vigilancia", "actividad": "Entrega al área de admisión el pase de salida."}, {"num": "5.9", "responsable": "Ama de llaves", "actividad": "Avisa al personal de intendencia del egreso, dependiendo del área que sea el paciente (Juan Pablo II, Planta Baja, Planta Alta, Ginecología, Terapia Intensiva, Pediatría, UCI)."}, {"num": "5.10", "responsable": "Ama de llaves", "actividad": "Tomará el vale de la habitación (FT-UV-16) correspondiente, el cual se encuentra en cada carpeta del séptico."}, {"num": "5.11", "responsable": "Ama de llaves", "actividad": "Verifica que el vale sea el correcto y esté firmado por UVEH, de acuerdo con el censo diario. Nota: En caso de no se encuentre vale o no esté firmado por UVEH, la ''Ama de llaves y/o Supervisora de Intendencia'', tienen la injerencia para firmar vale y autorizar aseo."}, {"num": "5.12", "responsable": "Ama de llaves", "actividad": "Notifica al personal de enfermería para el retiro de equipo biomédico y ropa."}, {"num": "5.13", "responsable": "Ama de llaves", "actividad": "Si el aseo es Exhaustivo (IT-IN-01) pasar al paso 5.17. Si el aseo es exhaustivo supervisado + Nebulizado (PR-IN-02), pasar al paso 5.22."}, {"num": "5.14", "responsable": "Enfermería", "actividad": "Retira y clasifica desechos generados en la atención médica (flebotek, frascos de soluciones, cánula nasal, etc.) y desinfecta el equipo biomédico que se haya utilizado en el paciente (bombas de infusión, monitor cardiaco)."}, {"num": "5.15", "responsable": "Enfermería", "actividad": "Retira la ropa sucia y/o contaminada de la habitación, verificando que no contenga residuos de desechos: pañales, equipos, punzocortante, etc. (IT-JE-27)."}, {"num": "5.16", "responsable": "Enfermería", "actividad": "Firma (FT-UV-16) en el apartado de ''retiro de ropa y equipo biomédico''."}, {"num": "5.17", "responsable": "Intendencia Operativo", "actividad": "Inicia el aseo de la habitación si el aseo establecido en el vale corresponde a ''exhaustivo'' (FT-UV-16) previamente llenado por el área de Epidemiología y establecido en el censo diario. Tipos de aseos: Exhaustivo (IT-IN-01), Exhaustivo supervisado + Nebulizado (PR-IN-02), Cultivo (PR-IN-01). Nota: en caso de ser aseo ''Exhaustivo supervisado + Nebulizado o Cultivo''. Primero se nebulizará la habitación."}, {"num": "5.18", "responsable": "Intendencia Operativo", "actividad": "Al terminar el aseo, el personal coloca jabón, papel higiénico y bolsas en los cestos para basura."}, {"num": "5.19", "responsable": "Intendencia Operativo", "actividad": "Firma el vale de acción o actividad concluida (FT-UV-16) y deja en el fichero de la habitación."}, {"num": "5.20", "responsable": "Ama de Llaves", "actividad": "Avisa a mantenimiento para realizar el Check list de habitaciones y/o Cubículos."}, {"num": "5.21", "responsable": "Mantenimiento", "actividad": "El personal realiza el Check list (PR-SG-12) que consiste en revisar que funcione la cama, tomas de aire, baño, aire acondicionado, televisión, teléfono, pagadores, puerta, etc. Y una vez revisado se firma el vale FT-UV-16. Nota: Si la habitación requiere reparación, avisa admisión para que ponga la leyenda en el censo y en el vale en la opción de nota: especifica la falla."}, {"num": "5.22", "responsable": "Intendencia Operativo", "actividad": "Si la habitación requirió desinfección ambiental (nebulización), el personal nebulizará el área. FT-SG-08 Control de áreas nebulizadas. (Esta acción se hará antes de realizar el aseo y se aprovechará para retirar cortinas). Nota: Para poder ingresar a la habitación deberá contar con su equipo de protección (cubrebocas, bata de manga larga e Higiene de manos)."}, {"num": "5.23", "responsable": "Intendencia Operativo", "actividad": "Firma el vale (FT-UV-16), se colocará el vale en el fichero."}, {"num": "5.24", "responsable": "Ama de Llaves", "actividad": "En caso de que el aseo esté indicado como Cultivo (PR-IN-01), la ama de llaves avisará al personal de laboratorio para hacer la toma de muestra y pegará el vale en la puerta y colocará el letrero de ''CULTIVO'' en la habitación."}, {"num": "5.25", "responsable": "Laboratorio", "actividad": "Antes de ingresar a la habitación a realizar la acción como lo especifica (PR-IN-01)."}, {"num": "5.26", "responsable": "Laboratorio", "actividad": "Se toma la muestra de superficies y firma el vale de actividad concluida y deja en el fichero."}, {"num": "5.27", "responsable": "Laboratorio", "actividad": "Cierra con llave habitación hasta que el resultado se reporte como negativo, por parte de UVEH."}, {"num": "5.28", "responsable": "Laboratorio", "actividad": "Registra cultivo en ''bitácora de laboratorio: control de calidad de habitaciones y/o cubículos'' (FT-UV-13). Nota: Se registran resultados a las 24 horas, 48 horas y 72 horas y se le informará al personal de UVEH la evolución del resultado."}, {"num": "5.29", "responsable": "Laboratorio", "actividad": "Notifica a UVEH el resultado final a través de un Reporte de cultivo de control (FT-UV-13)."}, {"num": "5.30", "responsable": "UVEH", "actividad": "El personal de UVEH firma la bitácora de control de calidad habitaciones y/o cubículos, registra el resultado del cultivo, firma y se libera la habitación si el resultado es NEGATIVO. Si el resultado es POSITIVO notificará a Supervisión de Intendencia y Ama de llaves para que no retire la leyenda del censo diario. Realiza nuevo vale de limpieza para iniciar nuevamente con el ciclo."}, {"num": "5.31", "responsable": "Ama de Llaves", "actividad": "Una vez notificado por la UVEH que la habitación es segura, se libera para el uso de un nuevo ingreso."}, {"num": "5.32", "responsable": "Ama de Llaves", "actividad": "Avisa a ropería para solicitud de cortinas de la habitación."}, {"num": "5.33", "responsable": "Ama de Llaves", "actividad": "Notifica a enfermería para el tendido de la cama."}, {"num": "5.34", "responsable": "Ama de Llaves", "actividad": "Notifica a mantenimiento para la colocación de cortinas."}, {"num": "5.35", "responsable": "Mantenimiento", "actividad": "Coloca las cortinas."}, {"num": "5.36", "responsable": "Enfermería", "actividad": "Acude al almacén de ropería de su área, y toma la ropa que requiere para el tendido de cama."}, {"num": "5.37", "responsable": "Enfermería", "actividad": "Firma ''Vale de control para la preparación de habitaciones de habitación y/o Cubículos'' (FT-UV-16) de actividad concluida y deja el en el tarjetero."}, {"num": "5.38", "responsable": "Enfermería", "actividad": "Notifica a la ama de llaves de actividad concluida."}, {"num": "5.39", "responsable": "Ama de Llaves", "actividad": "Verifica que el vale esté completo por todos los involucrados (FT-UV-16) y cierra habitación."}]'::jsonb,
  '[{"riesgo": "Adquirir agentes patógenos durante el proceso de limpieza.", "barrera": "Utilización de equipo de barrera (Bata, cubrebocas, guantes), para realizar la limpieza y desinfección de habitaciones y/o cubículos."}, {"riesgo": "No garantizar calidad y seguridad de la habitación; y el paciente adquiera alguna infección hospitalaria.", "barrera": "Utilización de equipo de barrera (Bata, cubrebocas, cofia), para realizar procesos de desinfección ambiental y toma de cultivo, evitando la contaminación de la habitación."}, {"riesgo": "Incumplimiento de sus actividades cada uno de los departamentos.", "barrera": "Capacitación al personal involucrado, para lograr la desinfección adecuada en cada uno del cubículo y/o habitaciones."}]'::jsonb,
  '[{"nombre": "NORMA Oficial Mexicana NOM-045-SSA2-2005, Para la vigilancia epidemiológica, prevención y control de las infecciones nosocomiales.", "codigo": ""}, {"nombre": "Bitácora laboratorio: de control de calidad de habitaciones y/o cubículos.", "codigo": "FT-UV-13"}, {"nombre": "Control de áreas nebulizadas", "codigo": "FT-SG-08"}, {"nombre": "Vale de control para la preparación de habitaciones y/o cubículos.", "codigo": "FT-UV-16"}, {"nombre": "Check list mantenimiento", "codigo": "PR-SG-12"}, {"nombre": "Aseo tipo ''Cultivo''", "codigo": "PR-IN-01"}, {"nombre": "Aseo tipo Exhaustivo, Supervisado y Nebulizado", "codigo": "PR-IN-01"}, {"nombre": "Aseo Exhaustivo de Habitaciones (Área crítica).", "codigo": "TI-IN-01"}, {"nombre": "Egreso de paciente de habitación", "codigo": "IT-JE-29"}, {"nombre": "Instrucción de trabajo para el retiro y clasificación de ropa sucia o contaminada", "codigo": "IT-JE-27"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}, {"version": "02", "fecha": "08/02/2024", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}, {"version": "03", "fecha": "29/08/2024", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}, {"version": "04", "fecha": "26/09/2025", "descripcion": "Actualización de formato", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de Vigilancia Epidemiológica Hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Médico Tratante / Admisión / Epidemiología / Enfermería / Intendencia / Mantenimiento / Laboratorio."}, {"tipo": "Supervisión", "descripcion": "Unidad de Vigilancia Epidemiológica Hospitalaria (UVEH)."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;


-- PR-UV-03
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-03'),
  'El proceso empieza cuando personal de epidemiología supervisa la bitácora y formatos de los niveles de cloro y finaliza cuando corrobora que la cloración se encuentre en los rangos permisibles.',
  'Supervisar los límites permisibles de calidad del agua para su uso, como lo marca la Norma Oficial Mexicana 127; previniendo que el agua esté asociado a microorganismos patógenos.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "UVEH / Epidemiología", "actividad": "Supervisará 1 vez por semana los registros de cloración de agua que realiza mantenimiento de manera diaria de las cisternas de: Capilla, Juan Pablo II, Cocina, Osmosis y Torre de Sótano, a través del formato de servicios básicos (FT-SG-19)."}, {"num": "5.2", "responsable": "UVEH / Epidemiología", "actividad": "Además se supervisará la bitácora cloración del agua, el cual monitorea los niveles de cloro de los grifos de todos los servicios: UCIN, pediatría, cardiología, planta alta, aislados, planta baja, cuneros, ginecología, toco cirugía, laboratorio, juan pablo II, quirófano, UTI, rayos x, hemodinámica, rehabilitación, urgencias, hemodinámica, endoscopia, por parte del personal de seguridad e higiene."}, {"num": "5.3", "responsable": "UVEH / Epidemiología", "actividad": "Verificará que los niveles de cloro sean adecuados en los dos registros y en caso de detectar que los niveles no sean óptimos, se notificará al personal de seguridad e higiene y medio ambiente."}, {"num": "5.4", "responsable": "UVEH / Epidemiología", "actividad": "Supervisa una vez al mes el manejo del Test Kit, lo realicen como corresponde y los datos de los niveles de cloro no sean manipulados."}, {"num": "5.5", "responsable": "Seguridad e higiene y medio ambiente", "actividad": "Una vez detectado que los niveles no son adecuados solicita a una empresa subrogada la medición de niveles de cloro, que cumpla con lo establecido en la Norma Oficial Mexicana (NOM-127-SSA1-1994, ''Salud ambiental, agua para uso y consumo humano-límites permisibles de calidad y tratamientos a que debe someterse el agua para su potabilización'')."}, {"num": "5.6", "responsable": "Empresa subrogada", "actividad": "Toma muestra del agua de las cisternas y analiza."}, {"num": "5.7", "responsable": "Empresa subrogada", "actividad": "Emite resultados y notifica a Seguridad e higiene y medio ambiente. Nota: en caso de que los niveles no sean adecuados, se dará la indicación al personal de mantenimiento para regular los niveles de cloro."}, {"num": "5.8", "responsable": "Personal de mantenimiento", "actividad": "Regula los niveles de cloro de las cisternas, y mide a través del Test Kit."}, {"num": "5.9", "responsable": "Personal de mantenimiento", "actividad": "Una vez regulados los niveles de cloro en cisternas, se monitorea también en los grifos de todos los servicios, asegurando que los niveles sean óptimos. Nota: si los niveles siguen siendo inadecuados, se avisa a seguridad e higiene y medio ambiente, para nuevas indicaciones para regulación."}, {"num": "5.10", "responsable": "Seguridad e higiene y medio ambiente", "actividad": "Solicita nueva toma de muestra por parte de la empresa subrogada."}, {"num": "5.11", "responsable": "Empresa subrogada", "actividad": "Toma muestra del agua de las cisternas y analiza."}, {"num": "5.12", "responsable": "Empresa subrogada", "actividad": "Emite resultados y notifica a Seguridad e higiene y medio ambiente. Nota: si los niveles siguen siendo inadecuados, se avisa a seguridad e higiene y medio ambiente, para nuevas indicaciones para regulación."}, {"num": "5.13", "responsable": "UVEH", "actividad": "Verifica que los niveles de cloro estén en los rangos establecidos."}]'::jsonb,
  '[{"riesgo": "Riesgo de contaminación por agentes patógenos en el agua.", "barrera": "Control de cloración del agua para garantizar su inocuidad."}, {"riesgo": "Desconocimiento del proceso y alteración de los mismos.", "barrera": "Capacitación del proceso y supervisión del proceso por parte del área de epidemiología."}]'::jsonb,
  '[{"nombre": "Bitácora de cloración de agua.", "codigo": "NA"}, {"nombre": "Norma Oficial Mexicana NOM-127-SSA1-1994, Salud ambiental. Agua para uso y consumo humano. Límites permisibles de calidad y tratamientos a que debe someterse el agua para su potabilización.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}, {"version": "02", "fecha": "08/02/2024", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de formato", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Epidemiología, personal de Mantenimiento, Seguridad higiene y medio ambiente, Empresa Subrogada."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;


-- PR-UV-06
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-06'),
  'Este procedimiento inicia desde epidemiología identifica el paciente y, finaliza cuando se recibe notificación secretaria de salud y archiva estudio epidemiológico.',
  'Esta actividad consiste en notificar en tiempo y en forma a la secretaría de Salud Jalisco (Región Sanitaria XIII), los pacientes con patologías que son consideradas de notificación inmediata, antes de transcurrir 24 horas de que se tenga conocimiento por el notificante o el informante de la ocurrencia del padecimiento o evento.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Aux. de Epidemiología", "actividad": "Se realiza instrucción de vigilancia activa y se capta al paciente con alguna de las siguientes patologías: Poliomielitis, parálisis flácida aguda, sarampión, enfermedad febril exantemática, difteria, tos ferina, síndrome coqueluchoide, cólera, tétanos, tétanos neonatal, tuberculosis meníngea, meningoencefalitis amibiana primaria, fiebre amarilla, peste, fiebre recurrente, tifo epidémico, tifo endémico o murino, fiebre manchada meningitis meningocócica, influenza, encefalitis equina venezolana, sífilis congénita, dengue grave, paludismo por Plasmodium falciparum, rabia humana, rubéola congénita, eventos adversos temporalmente asociados a la vacunación y substancias biológicas, lesiones por abeja africanizada, síndrome de inmunodeficiencia adquirida, infección por VIH y además, se debe notificar inmediatamente la presencia de brotes o epidemias de cualquier enfermedad, urgencias o emergencias epidemiológicas y desastres. Nota: Si se requiere muestra de sangre del paciente con alguna de estas patologías, epidemiología tendría que solicitarla."}, {"num": "5.2", "responsable": "Laboratorio", "actividad": "Toma muestras correspondientes, etiqueta y procesa."}, {"num": "5.3", "responsable": "Aux. de Epidemiología", "actividad": "Se hace el llenado del estudio epidemiológico correspondiente."}, {"num": "5.4", "responsable": "Aux. de Epidemiología", "actividad": "Se notifica a la región sanitaria y al jefe de epidemiología mediante los siguientes correos electrónicos: Silvia Medina silvia.medina@jalisco.gob.mx"}, {"num": "5.5", "responsable": "Aux. de Epidemiología", "actividad": "Avisa al jefe de mantenimiento para que lleven muestra al Laboratorio Estatal de Salud Pública (LESP)."}, {"num": "5.6", "responsable": "Región Sanitaria XIII", "actividad": "Envía por correo electrónico oficio para el envío de muestra."}, {"num": "5.7", "responsable": "Aux. de Epidemiología", "actividad": "Recibe documentación por parte de la región sanitaria y prepara la muestra."}, {"num": "5.8", "responsable": "Mantenimiento", "actividad": "Revisa documentación y lleva la muestra al lugar correspondiente."}, {"num": "5.9", "responsable": "Mantenimiento", "actividad": "Entrega documentación al personal de UVEH."}, {"num": "5.10", "responsable": "Aux. de Epidemiología", "actividad": "Archiva estudio epidemiológico en carpeta correspondiente."}]'::jsonb,
  '[{"riesgo": "Notificación tardía de enfermedades de interés epidemiológico.", "barrera": "Supervisión diaria en todos los servicios por parte de UVEH."}, {"riesgo": "Adquirir agentes patógenos durante la visita a los diferentes servicios.", "barrera": "Utilización de medidas de protección (Bata, cubrebocas, y en dado que se ocupe guantes)."}]'::jsonb,
  '[{"nombre": "Formato electrónico SUIVE-1-2019", "codigo": "NA"}, {"nombre": "Norma Oficial Mexicana NOM-017-SSA2-2012, Para la vigilancia epidemiológica.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/09/2023", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "Estudio epidemiológico", "definicion": "Consiste en la observación de la frecuencia y distribución de una enfermedad en un grupo de población definido y para un periodo de tiempo determinado, analizando los casos que se presentan o la mortalidad a que han dado lugar, así como los factores que influyen en su desarrollo. Se realiza en el entorno natural de los individuos observados y se consideran sus hábitos de vida."}]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH), Laboratorio, Región Sanitaria XIII, Mantenimiento, Laboratorio Estatal de Salud Pública."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
