  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;


-- PR-UV-07
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-07'),
  'Este procedimiento inicia desde que epidemiología identifica paciente y, finaliza cuando se recibe notificación secretaria de salud y epidemiologia archiva estudio epidemiológico.',
  'Esta actividad consiste en notificar mediante correo electrónico en tiempo y forma a la secretaría de Salud Jalisco (Región Sanitaria XIII), los pacientes con patologías que son consideradas de notificación diaria.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Aux. de Epidemiología", "actividad": "Se realiza instrucción de vigilancia activa y se capta al paciente con alguna de las siguientes patologías: Enfermedades prevenibles por vacunación: poliomielitis, parálisis flácida aguda, sarampión, difteria, tos ferina, tétanos, tuberculosis meníngea, rubéola y síndrome de rubéola congénita. Enfermedades infecciosas del aparato digestivo: cólera, amibiasis intestinal, shigelosis, fiebre tifoidea, intoxicación alimentaria bacteriana. Enfermedades infecciosas del aparato respiratorio: angina estreptocócica, infecciones respiratorias agudas, neumonías, tuberculosis e influenza. Enfermedades de transmisión sexual: sífilis adquirida, sífilis congénita, síndrome de inmunodeficiencia adquirida, infección por VIH, infección gonocócica, candidiosis urogenital, herpes genital, tricomoniasis urogenital. Enfermedades transmitidas por vectores: dengue no grave, dengue con signos de alarma o grave, tifo epidémico, fiebre manchada, paludismo por Plasmodium falciparum y Plasmodium vivax. Zoonosis: rabia, brucelosis, leptospirosis humanas, triquinelosis, teniasis, cisticercosis. Otras enfermedades exantemáticas: varicela, escarlatina y erisipela. Otras enfermedades transmisibles: conjuntivitis hemorrágica epidémica, hepatitis vírica A, hepatitis vírica B, meningitis meningocócica, parotiditis epidémica, escabiasis. Otras enfermedades no transmisibles: fiebre reumática aguda, hipertensión arterial, diabetes mellitus, enfermedades cerebrovasculares, asma, cirrosis hepática, intoxicación por plaguicidas, cáncer cérvicouterino. Nota: Si se requiere muestra de sangre del paciente con alguna de estas patologías, epidemiología tendría que solicitarla a laboratorio."}, {"num": "5.2", "responsable": "Laboratorio", "actividad": "Toma muestras correspondientes, etiqueta y procesa."}, {"num": "5.3", "responsable": "Aux. de Epidemiología", "actividad": "Se hace el llenado del estudio Epidemiológico correspondiente."}, {"num": "5.4", "responsable": "Aux. de Epidemiología", "actividad": "Se notifica a la región sanitaria y al jefe de epidemiologia mediante los siguientes correos electrónicos: Silvia Medina silvia.medina@jalisco.gob.mx"}, {"num": "5.5", "responsable": "Aux. de Epidemiología", "actividad": "Avisa al jefe de mantenimiento para que lleven muestra al Laboratorio Estatal de Salud Pública (LESP)."}, {"num": "5.6", "responsable": "Región Sanitaria XIII", "actividad": "Envía por correo electrónico oficio para el envío de muestra."}, {"num": "5.7", "responsable": "Aux. de Epidemiología", "actividad": "Recibe documentación por parte de la región sanitaria y prepara la muestra."}, {"num": "5.8", "responsable": "Mantenimiento", "actividad": "Revisa documentación y lleva la muestra al lugar correspondiente."}, {"num": "5.9", "responsable": "Mantenimiento", "actividad": "Entrega documentación al personal de UVEH."}, {"num": "5.10", "responsable": "Aux. de Epidemiología", "actividad": "Archiva estudio epidemiológico en carpeta correspondiente. Nota: estos casos independientemente que se notifiquen diariamente, se tendrán que notificar mediante al Sistema Único Automatizado de Vigilancia Epidemiológica (SUIVE)."}]'::jsonb,
  '[{"riesgo": "Notificación tardía de enfermedades de interés epidemiológico.", "barrera": "Supervisión diaria en todos los servicios por parte de UVEH."}, {"riesgo": "Adquirir agentes patógenos durante la visita a los diferentes servicios.", "barrera": "Utilización de medidas de protección (Bata, cubrebocas, y en dado que se ocupe guantes)."}]'::jsonb,
  '[{"nombre": "Formato electrónico SUIVE-1-2019", "codigo": "NA"}, {"nombre": "Norma Oficial Mexicana NOM-017-SSA2-2012, Para la vigilancia epidemiológica.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/09/2023", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "Estudio epidemiológico", "definicion": "Consiste en la observación de la frecuencia y distribución de una enfermedad en un grupo de población definido y para un periodo de tiempo determinado, analizando los casos que se presentan o la mortalidad a que han hado lugar, así como los factores que influyen en su desarrollo. Se realiza en el entorno natural de los individuos observados y se consideran sus hábitos de vida."}]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH), Laboratorio, Región Sanitaria XIII, Mantenimiento, Laboratorio Estatal de Salud Pública."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
