SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-08'),
  'Este proceso inicia con la planeación del cronograma de capacitación de higiene de manos y termina cuando vigilancia epidemiológica vigila el cumplimiento de ello.',
  'Capacitar al personal clínico, no clínico, en formación, subrogado, voluntariado y visitantes, sobre la Higiene de Manos, con el fin de prevenir Infecciones Asociadas con la Atención de Salud.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "UVEH", "actividad": "Realiza cronograma de capacitaciones anuales fechas y horarios establecidos por servicio (Valorando la necesidad de capacitación del personal en general de acuerdo con sus actividades)."}, {"num": "5.2", "responsable": "UVEH", "actividad": "Crea material de apoyo acorde al tema Higiene Manos (IT-UV-01). Apegado a los lineamientos otorgados por la OMS."}, {"num": "5.3", "responsable": "UVEH", "actividad": "Determina el método con el cual se impartirá la capacitación."}, {"num": "5.4", "responsable": "UVEH", "actividad": "Se envía memorándum con anticipación a jefatura de cada área el cronograma de capacitaciones."}, {"num": "5.5", "responsable": "UVEH / Jefatura de Enseñanza Enfermería", "actividad": "Se asiste puntualmente en la hora y fecha acordada para la impartición de la capacitación. Nota: En el caso específicamente de enfermería, se realiza capacitación en conjunto con la Jefatura de Enseñanza de Enfermería, con el fin de estar en la misma sintonía. PR-JE-07"}, {"num": "5.6", "responsable": "UVEH", "actividad": "Se evidenciará por medio de listas de asistencia, así como el contenido del tema."}, {"num": "5.7", "responsable": "UVEH", "actividad": "Se realizará periódicamente la monitorización, la evaluación del tema y el cumplimiento del proceso."}, {"num": "5.8", "responsable": "UVEH", "actividad": "Aplicando un estudio de sombra, y registrando en el formato de evaluación IT-UV-15."}]'::jsonb,
  '[{"riesgo": "Disponer de poco tiempo para asistir a la capacitación por un aumento en la demanda de los servicios hospitalarios.", "barrera": "Valorar los tiempos adecuados para lograr la asistencia a la capacitación."}, {"riesgo": "Desinterés y apatía del personal en la asistencia a capacitaciones continuas.", "barrera": "Fomentar y crear conciencia de la importancia de mantenerse actualizado en los procesos de atención al paciente."}, {"riesgo": "No realizar seguimiento a la realización del proceso de lavado de manos.", "barrera": "Programar fechas específicas de capacitación y de evaluación de seguimiento del proceso de lavado de manos."}]'::jsonb,
  '[{"nombre": "Proceso de Capacitación de lavado de manos", "codigo": "PR-JE-07"}, {"nombre": "Instrucción de trabajo Higiene de manos de la unidad de epidemiología", "codigo": "IT-UV-01"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}, {"version": "02", "fecha": "08/02/2024", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de formato", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH), Departamento de enseñanza."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
