-- PR-UV-10
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-10'),
  'Este proceso inicia cuando el departamento de epidemiología identifica riesgos, eventos o situaciones epidemiológicas hasta que se realiza comunicado de término de alerta.',
  'Detectar oportunamente riesgos, eventos o situaciones de emergencia epidemiológica, con el propósito de implementar las acciones de prevención y control correspondientes, a fin de reducir su impacto en la salud de la población.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "UVEH", "actividad": "Monitorea alertas epidemiológicas a través de fuentes oficiales las alertas epidemiológicas: Instituciones del Sector Salud a través del CONAVE y de los CEVE."}, {"num": "5.2", "responsable": "UVEH", "actividad": "Convoca de manera extraordinaria al comité para la Detección y control de las infecciones asociadas a la atención de salud (CODECIAAS)."}, {"num": "5.3", "responsable": "CODECIAAS", "actividad": "Se realiza sesión y se da conocer la alerta epidemiológica, se llegan acuerdos, compromisos y estrategias."}, {"num": "5.4", "responsable": "UVEH", "actividad": "Emite circular de alerta, con las siguientes características: Título del aviso o alerta; Numeración consecutiva para avisos o alertas; Fecha de emisión; Destinatarios. Situación epidemiológica: Antecedentes del evento; Situación epidemiológica; Acciones de vigilancia epidemiológica. Medidas de prevención y control: Personal de salud; Población en general. Nota: En caso de que el evento se trate de una enfermedad que amerite una alerta epidemiológica se deberán incluir: Definiciones operacionales de caso; Especificaciones para el diagnóstico por laboratorio."}, {"num": "5.5", "responsable": "UVEH", "actividad": "Programación de capacitaciones en caso de implementarse nuevos procesos."}, {"num": "5.6", "responsable": "UVEH", "actividad": "Realización de informes con datos estadísticos y epidemiológicos."}, {"num": "5.7", "responsable": "Dirección Médica", "actividad": "Realiza los informes a la Asociación de Hospitales Particulares."}, {"num": "5.8", "responsable": "UVEH", "actividad": "Elaborará comunicado de término alerta epidemiológica."}]'::jsonb,
  '[{"riesgo": "Omisión de las indicaciones emitidas por el comité.", "barrera": "Apego estricto por parte de las jefaturas para el cumplimiento de los objetivos establecidos."}, {"riesgo": "Desconocimiento de la alerta epidemiológica y nuevos procesos.", "barrera": "Capacitaciones de nuevos procesos y supervisión."}]'::jsonb,
  '[{"nombre": "Norma Oficial Mexicana NOM-017-SSA2-2012, Para la vigilancia epidemiológica.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/09/2023", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "Alerta epidemiológica", "definicion": "Comunicado sobre un evento epidemiológico que representa un daño inminente a la salud de la población y/o de trascendencia social, frente al cual es necesario ejecutar acciones de salud inmediatas y eficaces con el fin de minimizar o contener su ocurrencia. Para las entidades federativas se denomina alerta epidemiológica estatal."}]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH), Comité para la Detección y control de las infecciones asociadas a la atención de salud (CODECIAAS) y Dirección Médica."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;


-- PR-UV-11
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-11'),
  'Este proceso inicia desde que el médico tratante sospecha paciente con diagnóstico de enfermedad infectocontagiosa, y termina cuando el médico realiza la suspensión del aislamiento ya sea el motivo de ingreso o ésta sea detectada durante el período de hospitalización y se le da el debido proceso de aislamiento de acuerdo con la patología identificada.',
  'Interrumpir la cadena de transmisión de una enfermedad infecciosa, a fin de prevenir el contagio entre los pacientes, y el personal hospitalario; así como el personal en contacto con el entorno del paciente y a familiares o visitantes.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Médico Tratante", "actividad": "Indica el ingreso de paciente, con su diagnóstico establecido."}, {"num": "5.2", "responsable": "Admisión", "actividad": "Realiza el trámite de ingreso administrativo y avisa a supervisión de enfermería. PR-CS-01"}, {"num": "5.3", "responsable": "Supervisión Enfermería", "actividad": "Revisa indicaciones y detecta paciente infeccioso o con sospecha de infección."}, {"num": "5.4", "responsable": "Supervisión Enfermería", "actividad": "Determina habitación de aislamiento y medida precautoria a implementar (Contacto, Gota, aérea, MDRO). (FT-UV-05). Nota: En caso de tener duda avisa al departamento de UVEH."}, {"num": "5.5", "responsable": "Médico de Guardia", "actividad": "Realiza visita e identifica paciente con sospecha clínica o con diagnóstico certero de paciente infeccioso y avisa al departamento de UVEH, Supervisión de enfermería y determina la media precautoria a implementar. (FT-UV-05)"}, {"num": "5.6", "responsable": "Médico de Guardia", "actividad": "Notifica al médico tratante del aislamiento en caso de no conocerlo."}, {"num": "5.7", "responsable": "Enfermería", "actividad": "Coloca en la habitación mediada precautoria correspondiente al ingreso de la habitación. (FT-UV-05)"}, {"num": "5.8", "responsable": "Enfermería", "actividad": "Realizar higiene de manos durante los 5 momentos (IT-UV-01) y (IT-UV-04)"}, {"num": "5.9", "responsable": "Enfermería", "actividad": "Colocar adecuadamente el equipo de protección correspondiente: Usar bata de manga larga (IT-UV-05); Colocación correcta del cubrebocas (IT-UV-06)."}, {"num": "5.10", "responsable": "Enfermería", "actividad": "Manejo adecuado de los Residuos Peligrosos Biológicos e Infecciosos, así como desecho adecuado de punzocortantes."}, {"num": "5.11", "responsable": "Enfermería", "actividad": "Se deberá explicar al paciente y a sus familiares o visitantes la razón del aislamiento, así como la importancia de utilizar el equipo de protección, donde solicitarlo y el manejo posterior a su uso, ejemplo: cubre boca, guantes. Nota: el personal deberá explicar al familiar cómo se coloca el equipo de protección."}, {"num": "5.12", "responsable": "Enfermería", "actividad": "Los dispositivos médicos que estén en contacto con el paciente deberán desinfectarse con frecuencia. (IT-JE-45)"}, {"num": "5.13", "responsable": "Enfermería", "actividad": "Los equipos biomédicos serán desinfectados o esterilizados una vez que el paciente egrese del hospital. Nota: en caso de que requiera quedar en ''cultivo'', UVEH los determinará."}, {"num": "5.14", "responsable": "Todo Personal Clínico y No Clínico", "actividad": "Todo personal que requiera ingresar a la habitación deberá respetar las medidas precautorias establecidas."}, {"num": "5.15", "responsable": "Laboratorio", "actividad": "Informar inmediatamente al departamento de UVEH si detecta y/o aísla gérmenes multirresistentes en cultivos del paciente. Nota: si el resultado del cultivo corresponde a una IAAS (caso nuevo) se avisa a los departamentos involucrados y se inicia el aislamiento."}, {"num": "5.16", "responsable": "UVEH", "actividad": "Avisa a los supervisores de enfermería y médicos de guardia y modifica tipo de aseo para habitación."}, {"num": "5.17", "responsable": "Intendencia", "actividad": "En las habitaciones con paciente en aislamiento deberá realizarse el aseo rutinario y aseo ''Exhaustivo Supervisado + Nebulizado'' cuando éste sea dado de alta. Nota: En dado caso que epidemiología detecte algunos gérmenes multirresistentes, se hará como aseo ''Cultivo''."}, {"num": "5.18", "responsable": "Médico Tratante", "actividad": "Registrar en las indicaciones la suspensión de aislamiento del paciente, cuando haya desaparecido la condición o patología que así lo requería."}, {"num": "5.19", "responsable": "UVEH", "actividad": "Si existiese alguna duda o controversia en cuanto al manejo del paciente con enfermedad infectocontagiosa se comunicarán con los responsables de la Unidad Vigilancia Epidemiológica Hospitalaria."}]'::jsonb,
  '[{"riesgo": "Omisión del proceso por parte del personal clínico.", "barrera": "Capacitaciones al personal clínico de las medidas precautoria Inversa."}, {"riesgo": "Brotes de infecciones por mal manejo del paciente infeccioso.", "barrera": "Asignación estratégica de habitaciones para pacientes y supervisión continua."}]'::jsonb,
  '[{"nombre": "Medidas precautorias", "codigo": "FT-UV-05"}, {"nombre": "Instrucción de trabajo para la higiene de manos con agua y jabón.", "codigo": "IT-UV-01"}, {"nombre": "Instrucción de trabajo para la higiene de manos con gel alcoholado.", "codigo": "IT-UV-04"}, {"nombre": "Colocación correcta de bata", "codigo": "IT-UV-05"}, {"nombre": "Colocación correcta del cubrebocas", "codigo": "IT-UV-06"}, {"nombre": "Proceso para el abastecimiento de insumos para la higiene de manos", "codigo": "PR-UV-01"}, {"nombre": "Desmontaje y sanitización de material", "codigo": "IT-JE-45"}, {"nombre": "Limpieza y desinfección de habitaciones", "codigo": "IT-IN-01"}, {"nombre": "Guía De Aplicación De La Estrategia Multimodal De La OMS, Para La Mejora De La Higiene De Manos (2010).", "codigo": "NA"}, {"nombre": "Norma Oficial Mexicana Nom-045-Ssa2-2015, Para La Vigilancia Epidemiológica, Prevención Y Control De Las Infecciones Nosocomiales.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/09/2023", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "IAAS", "definicion": "Las Infecciones Asociadas a la Atención de la Salud (IAAS), se definen de acuerdo con la Organización Mundial de la Salud (OMS), como aquellas infecciones que afectan a un paciente durante el proceso de asistencia en un hospital o Centro Sanitario, que no estaba presente, ni en período de incubación al momento de su ingreso y que pueden inclusive llegar a manifestarse después del alta del paciente."}]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Médico tratante, admisión, supervisión de enfermería, médico de guardia, enfermería, personal clínico/no clínico, laboratorio e intendencia y UVEH."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;


-- PR-UV-12
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-12'),
  'Este proceso inicia cuando el médico tratante indica el ingreso y finaliza cuando el personal de salud ingresa a la habitación con la medida precautoria correspondiente (Inversa) y aplica las funciones asistenciales.',
  'Unificar criterios para la adecuada aplicación del protocolo sobre aislamiento inverso, con el fin de prevenir Infecciones Asociadas a la atención de Salud (IAAS).',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Médico Tratante", "actividad": "Indica el ingreso del paciente, con su diagnóstico establecido."}, {"num": "5.2", "responsable": "Admisión", "actividad": "Realiza el trámite de ingreso administrativo y avisa a supervisión de enfermería. (PR-CS-01)"}, {"num": "5.3", "responsable": "Supervisión Enfermería", "actividad": "Revisa indicaciones y detecta paciente inmunodeprimido."}, {"num": "5.4", "responsable": "Supervisión Enfermería", "actividad": "Determina habitación de aislamiento y medida precautoria a implementar (Inversa-Lila). (FT-UV-05). Nota: En caso de tener duda avisa al departamento de UVEH."}, {"num": "5.5", "responsable": "Médico de Guardia", "actividad": "Realiza visita e identifica paciente con sospecha clínica o con diagnóstico certero de paciente inmunodeprimido y avisa al departamento de UVEH, Supervisión de enfermería y determina la medida precautoria a implementar. (FT-UV-05)"}, {"num": "5.6", "responsable": "Médico de Guardia", "actividad": "Notifica al médico tratante del aislamiento en caso de no conocerlo."}, {"num": "5.7", "responsable": "Enfermería", "actividad": "Coloca en la habitación medida precautoria correspondiente al ingreso de la habitación (inversa). (IT-UV-14). Nota: El tarjetón de colocarse en un lugar visible, esta será en la puerta de entrada y si el personal tiene alguna duda si se trata de un paciente inmunodeprimido o de que medida precautoria le corresponde, se puede basar en el formato FT-UV-05."}, {"num": "5.8", "responsable": "Enfermería", "actividad": "Realizar higiene de manos durante los 5 momentos (IT-UV-01) y (IT-UV-04)"}, {"num": "5.9", "responsable": "Enfermería", "actividad": "Colocar adecuadamente el equipo de protección correspondiente: Usar bata de manga larga (IT-UV-05); Colocación correcta del cubrebocas (IT-UV-06)."}, {"num": "5.10", "responsable": "Enfermería", "actividad": "Manejo adecuado de los Residuos Peligros Biológicos e Infecciosos, así como desecho adecuado de punzocortantes."}, {"num": "5.11", "responsable": "Enfermería", "actividad": "Se deberá explicar al paciente y a sus familiares o visitantes la razón del aislamiento, así como la importancia de utilizar el equipo de protección, donde solicitarlo, ejemplo: cubre boca y bata. Nota: el personal deberá explicar al familiar cómo se coloca el equipo de protección."}, {"num": "5.12", "responsable": "Enfermería", "actividad": "Los dispositivos médicos y biomédicos que está en contacto con el paciente deberán desinfectarse antes y después de usarse. (IT-JE-45)"}, {"num": "5.13", "responsable": "Todo Personal Clínico y No Clínico", "actividad": "Todo personal que requiera ingresar a la habitación deberá respetar las medidas precautorias establecidas."}, {"num": "5.14", "responsable": "Laboratorio", "actividad": "Informar inmediatamente al departamento de UVEH si detecta y/o aísla gérmenes multirresistentes en cultivos del paciente. Nota: si es el resultado del cultivo corresponde a una IAAS (caso nuevo) se avisa a los departamentos involucrados y se inicia el aislamiento infeccioso (PR-UV-11)."}, {"num": "5.16", "responsable": "UVEH", "actividad": "Avisa a los supervisores de enfermería y médicos de guardia y modifica el tipo de aseo para habitación."}, {"num": "5.17", "responsable": "Intendencia", "actividad": "En las habitaciones con paciente en aislamiento deberá realizarse el aseo rutinario y aseo ''Exhaustivo''."}]'::jsonb,
  '[{"riesgo": "Omisión del proceso por parte del personal clínico.", "barrera": "Capacitaciones al personal clínico de las medidas precautorias."}, {"riesgo": "Adquirir Infección Asociada a la atención de salud.", "barrera": "Asignación estratégica de habitaciones para pacientes inmunodeprimidos y supervisión continua."}]'::jsonb,
  '[{"nombre": "Medidas precautorias", "codigo": "FT-UV-05"}, {"nombre": "Precauciones inversa tarjeta lila", "codigo": "IT-UV-14"}, {"nombre": "Instrucción de trabajo para la higiene de manos con agua y jabón.", "codigo": "IT-UV-01"}, {"nombre": "Instrucción de trabajo para la higiene de manos con gel alcoholado.", "codigo": "IT-UV-04"}, {"nombre": "Colocación correcta de bata", "codigo": "IT-UV-05"}, {"nombre": "Colocación correcta del cubrebocas", "codigo": "IT-UV-06"}, {"nombre": "Proceso para el abastecimiento de insumos para la higiene de manos", "codigo": "PR-UV-01"}, {"nombre": "Desmontaje y sanitización de material", "codigo": "IT-JE-45"}, {"nombre": "Limpieza y desinfección de habitaciones", "codigo": "IT-IN-01"}, {"nombre": "Procedimiento para el ingreso de pacientes a hospitalización.", "codigo": "PR-CS-01"}, {"nombre": "Guía De Aplicación De La Estrategia Multimodal De La OMS, Para La Mejora De La Higiene De Manos (2010).", "codigo": "NA"}, {"nombre": "Norma Oficial Mexicana Nom-045-Ssa2-2015, Para La Vigilancia Epidemiológica, Prevención Y Control De Las Infecciones Nosocomiales.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "03/06/2021", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/09/2023", "descripcion": "Modificación de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "IAAS", "definicion": "Las Infecciones Asociadas a la Atención de la Salud (IAAS), se definen de acuerdo con la Organización Mundial de la Salud (OMS), como aquellas infecciones que afectan a un paciente durante el proceso de asistencia en un hospital o Centro Sanitario, que no estaba presente, ni en período de incubación al momento de su ingreso y que pueden inclusive llegar a manifestarse después del alta del paciente."}, {"termino": "Medida precautoria inversa", "definicion": "Medida diseñada para evitar el acceso de microorganismos en pacientes con alta vulnerabilidad a las infecciones y son para proteger pacientes severamente inmunodeprimidos y no infectados."}]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Médico tratante, admisión, supervisión de enfermería, médico de guardia, enfermería, personal clínico/no clínico, laboratorio e intendencia, UVEH."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;-- PR-UV-13
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-13'),
  'Inicia cuando el departamento de epidemiología asegura que su personal esté capacitado para realizar cada una las actividades necesarias en el departamento y termina cuando el ''Comité para la Detección y Control de Infecciones Asociadas a la Atención de la Salud (CODECIAAS)'' gestiona los recursos necesarios.',
  'Asegurar que se cuenten con los recursos adecuados para desarrollar en forma efectiva el sistema de prevención y control de infecciones, como lo son insumos, personal competente y sistemas de información.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Recursos Humanos", "actividad": "El departamento de recursos humanos será encargado de reclutar personal capacitado y con experiencia para realizar actividades de vigilancia epidemiológica hospitalaria, establecido en la descripción de puesto. EM1"}, {"num": "5.2", "responsable": "Dirección Médica", "actividad": "Evalúa que el personal médico reclutado para jefe de epidemiología cuente con estudios en epidemiología y/o Infectología. EM2"}, {"num": "5.3", "responsable": "Epidemiología", "actividad": "Evalúa que el personal auxiliar reclutado tenga capacidades y habilidades, así como conocimientos indispensables en el área de epidemiología hospitalaria. EM2"}, {"num": "5.4", "responsable": "Dirección Médica y Epidemiología", "actividad": "El departamento de epidemiología respaldado por dirección médica será el responsable de gestionar los recursos físicos y financieros para la adquisición de material e insumos necesarios para garantizar la seguridad en cuanto a infecciones asociadas a la atención de salud corresponda. EM3 y EM4"}, {"num": "5.5", "responsable": "CODECIAAS", "actividad": "Cuando el departamento de epidemiología detecta los riesgos y problemas para la prevención y control de infecciones y no ha tenido éxito los recursos físicos y financieros, se recurre al Comité para la Detección y Control de Infecciones Asociadas a la Atención de la Salud (CODECIAAS) donde los integrantes del comité ayudarán a gestionar los recursos necesarios para la aplicación de acciones de mejora de los riesgos y/o problemas identificados. EM5."}]'::jsonb,
  '[{"riesgo": "Incidencia de infecciones asociadas a la atención de salud (IAAS) recurrentes.", "barrera": "Identificación oportuna de las infecciones asociadas a la atención de salud (IAAS) para la aplicación de medidas preventivas."}, {"riesgo": "Riesgos laborales por falta de insumos para la protección de nuestros colaboradores.", "barrera": "Monitoreo frecuentemente sobre los insumos necesarios para la atención sanitaria."}, {"riesgo": "Omisión de los procesos internos en la atención sanitaria.", "barrera": "Supervisión de los procesos internos y cumplimiento con lo requerido con las autoridades sanitarias."}]'::jsonb,
  '[{"nombre": "Norma Oficial Mexicana Nom-045-Ssa2-2015, Para La Vigilancia Epidemiológica, Prevención Y Control De Las Infecciones Nosocomiales.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "05/07/2021", "descripcion": "Alta de documento", "realizado": "Dr. Manuel Cortes Gutierrez", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/11/2023", "descripcion": "Alta de documento", "realizado": "Dr. Estebán González Díaz", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "IAAS", "definicion": "Las Infecciones Asociadas a la Atención de la Salud (IAAS), se definen de acuerdo con la Organización Mundial de la Salud (OMS), como aquellas infecciones que afectan a un paciente durante el proceso de asistencia en un hospital o Centro Sanitario, que no estaba presente, ni en período de incubación al momento de su ingreso y que pueden inclusive llegar a manifestarse después del alta del paciente."}, {"termino": "CODECIAAS", "definicion": "Son las siglas del Comité para la Detección y Control de Infecciones Asociadas a la Atención de la Salud."}]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Recursos Humanos, Unidad de Vigilancia Epidemiológica Hospitalaria (UVEH) y Dirección Médica."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
