-- PR-UV-19
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-19'),
  'Inicia cuando el departamento aplica proceso seguro del uso de medicamentos y termina cuando UVEH realiza muestreo y análisis microbiológico de manera aleatoria tanto en refrigeradores como de medicamentos almacenados, con la finalidad de prevenir infecciones.',
  'Garantizar el adecuado uso de los medicamentos y vacunas desde el punto de vista de prevención de infecciones.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Farmacovigilancia", "actividad": "Aplica proceso seguro del uso de medicamentos multidosis (PR-FH-06), así como Política (PL-FH-01) y proceso de administración de los medicamentos que trae consigo el paciente (PR-FH-02), con el objetivo de asegurar el cuidado de su medicación durante su estancia hospitalaria. EM1."}, {"num": "5.2", "responsable": "Intendencia", "actividad": "Se realiza limpieza de refrigeradores de alimentos, con el fin de evitar la contaminación bacteriana. (IT-IN-07) EM2"}, {"num": "5.3", "responsable": "Enfermería", "actividad": "Cuenta con los insumos necesarios de limpieza de mesas para la preparación de medicamentos hasta la aplicación de estos cuidando las técnicas correctas de asepsia. EM2"}, {"num": "5.4", "responsable": "UVEH", "actividad": "Realiza supervisión de los refrigeradores de medicamentos de las diferentes áreas, con la finalidad de detectar factores que contribuyen a contaminación de los medicamentos ahí resguardados (FTUV-22)."}, {"num": "5.5", "responsable": "UVEH", "actividad": "De manera anual se realizará muestreo y análisis microbiológico de manera aleatoria tanto en refrigeradores como de medicamentos almacenados, con la finalidad de prevenir infecciones."}]'::jsonb,
  '[{"riesgo": "Riesgo de contaminación microbiológica de los medicamentos por mal manejo.", "barrera": "Capacitación continúa del personal para el correcto uso de medicamentos."}, {"riesgo": "Infección a la paciente asociada a la atención sanitaria.", "barrera": "Supervisión constante por parte de epidemiología y muestreo microbiológico con fin de prevenir infecciones."}]'::jsonb,
  '[{"nombre": "Instrucción de trabajo para la limpieza y desinfección de refrigeradores de medicamentos.", "codigo": "IT-IN-07"}, {"nombre": "Supervisión de centrales y áreas.", "codigo": "FT-UV-22"}]'::jsonb,
  '[{"version": "01", "fecha": "05/07/2021", "descripcion": "Alta de documento", "realizado": "Dr. Manuel Cortes Gutiérrez", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "21/09/2022", "descripcion": "Modificación de documento", "realizado": "Dr. Manuel Cortes Gutiérrez", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Farmacovigilancia, Intendencia, Enfermería y UVEH."}, {"tipo": "Supervisión", "descripcion": "Dirección Médica."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
