-- PR-UV-20
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-20'),
  'Inicia cuando el auxiliar de epidemiología realiza vigilancia activa en hospital y termina cuando el jefe del departamento presenta el análisis de las tasas, patrones y tendencias en el ''Comité para la Detección y Control de Infecciones Asociadas a la Atención de la Salud (CODECIAAS)''.',
  'Reducir el riesgo de infecciones para los pacientes, personal y familiares, a través de supervisión y análisis de tasas, patrones y tendencias.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Auxiliar de UVEH", "actividad": "Realiza vigilancia epidemiológica ''Activa'', el cual consiste básicamente en la búsqueda intencionada de casos de enfermedades sujetas a vigilancia epidemiológica y de infecciones hospitalarias descritas en la instrucción de vigilancia activa IT-UV-17 y es el responsable de la notificación inmediata y mensual de las enfermedades que establece la normativa vigente. (Norma Oficial Mexicana NOM-017-SSA2-2012, para la vigilancia epidemiológica.) (EM7)"}, {"num": "5.2", "responsable": "Auxiliar de UVEH", "actividad": "Diariamente se monitorean los pacientes hospitalizados, con el fin de identificar oportunamente infecciones relacionadas a la atención sanitaria."}, {"num": "5.3", "responsable": "Auxiliar de UVEH", "actividad": "Una vez identificadas las infecciones se levanta estudio epidemiológico correspondiente (PR-UV-06 y PR-UV-07), se capturan los datos con el fin de formar indicadores, que ayuden analizar el comportamiento y tomar medidas preventivas. EM3"}, {"num": "5.4", "responsable": "CODECIAAS", "actividad": "El jefe encargado del departamento será el encargado de realizar indicadores de manera mensual de las infecciones hospitalarias, con el fin de medir, analizar y evaluar y estos resultados se presentan en las sesiones ordinarias del CODECIAAS. EM4"}, {"num": "5.5", "responsable": "CODECIAAS", "actividad": "Además realizará las tasas de infecciones relacionadas a la atención sanitaria, analizar los patrones y tendencias. EM2. Para poder realizar las tasas es importante obtener datos del departamento de sistemas del total de egresos por mes y para hacer análisis de los patrones y tendencias, se cuenta con datos históricos, que nos permiten realizar comparaciones."}, {"num": "5.6", "responsable": "CODECIAAS", "actividad": "Los resultados obtenidos siempre serán comparados con los estándares nacionales e internacionales, así como organizaciones estatales; con el único fin de apegarnos a los lineamientos establecidos. EM5"}, {"num": "5.7", "responsable": "CODECIAAS", "actividad": "De igual forma tendrán que ser presentados en las sesiones ordinarias del CODECIN, con la finalidad de mejorar procesos o generar estrategias para mejorar nuestros datos. EM6"}]'::jsonb,
  '[{"riesgo": "Sesgo en la información por no identificar oportunamente las infecciones.", "barrera": "Adiestramiento del personal de epidemiología para la identificación oportuna de los casos."}, {"riesgo": "Falta de información por parte del departamento de archivo clínico para la construcción de indicadores.", "barrera": "Compromiso por parte del departamento de archivo clínico para entrega oportuna cada mes de la información."}]'::jsonb,
  '[{"nombre": "Norma Oficial Mexicana NOM-017-SSA2-2012, para la vigilancia epidemiológica.", "codigo": "NA"}, {"nombre": "Vigilancia epidemiológica activa", "codigo": "IT-UV-17"}, {"nombre": "Notificación epidemiológica inmediata", "codigo": "PR-UV-06"}, {"nombre": "Notificación epidemiológica diaria", "codigo": "PR-UV-07"}]'::jsonb,
  '[{"version": "01", "fecha": "05/07/2021", "descripcion": "Alta de documento", "realizado": "Dr. Manuel Cortes Gutiérrez", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "21/09/2022", "descripcion": "Modificación de documento", "realizado": "Dr. Manuel Cortes Gutiérrez", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "CODECIAAS", "definicion": "Son las siglas del Comité para la Detección y Control de Infecciones Asociadas a la Atención de la Salud."}]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Auxiliar de UVEH, Jefatura de UVEH y CODECIAAS."}, {"tipo": "Supervisión", "descripcion": "Dirección Médica."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
  definiciones         = EXCLUDED.definiciones,
  responsabilidades    = EXCLUDED.responsabilidades;


-- PR-UV-21
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-21'),
  'Este procedimiento inicia la empresa subrogada entrega la ropa limpia hospitalaria y termina cuando la responsable de ropería hace la entrega de la ropa sucia y/o contaminada.',
  'Asegurar el buen manejo de la ropa hospitalaria desde su recepción hasta su disposición final.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Encargada de Ropería", "actividad": "Realiza recepción y almacenamiento de ropa limpia hospitalaria que la empresa subrogada renta al hospital. (PR-RO-02)"}, {"num": "5.2", "responsable": "Encargada de Ropería", "actividad": "Determinan el stock de ropa limpia de cada una de las áreas. (FT-RO-01)"}, {"num": "5.3", "responsable": "Encargada de Ropería / Jefatura de Enfermería", "actividad": "Realizan acuerdos de horarios de entrega y recepción de ropa limpia (FT-RO-04). PR-JE-02 MISP 2. Mejorar la comunicación efectiva."}, {"num": "5.4", "responsable": "Encargada de Ropería", "actividad": "Realiza abastecimientos de stock de ropa de cada área (IT-RO-1) y firma bitácora ''Entrega y recepción de ropa hospitalaria.'' (FT-RO-01)."}, {"num": "5.5", "responsable": "Enfermería (Operativo)", "actividad": "Recibe, realiza conteo y firma bitácora de ropa limpia de cada área. (FT-RO-01)"}, {"num": "5.6", "responsable": "Enfermería (Operativo)", "actividad": "Verifica que la ropa limpia entregada sea la correcta y suficiente para cubrir la demanda y necesidades del servicio."}, {"num": "5.7", "responsable": "Enfermería (Operativo)", "actividad": "Realiza manejo adecuado de la ropa limpia. Nota: En caso de requerir prendas extras avisará a la ropería para la gestión."}, {"num": "5.8", "responsable": "Médico Tratante", "actividad": "Indica egreso del paciente."}, {"num": "5.9", "responsable": "Enfermería (Operativo)", "actividad": "Procede hacer el retiro y clasificación de ropa sucia y/o contaminada. (IT-JE-27). Nota: la ropa contaminada no deberá depositarse en el tánico."}, {"num": "5.10", "responsable": "Intendencia", "actividad": "Traslada tánico con ropa sucia correspondiente a su área al cuarto de ''ropa sucia'' al contenedor temporal, cada que se encuentre al 90% de su capacidad. (PR-RO-01). Nota: el traslado de ropa al contenedor temporal se hará las veces que sean necesarias."}, {"num": "5.11", "responsable": "Intendencia", "actividad": "Realiza la separación y conteo de la ropa sucia generada; ropa propia y de la empresa subrogada. (PR-RO-01)"}, {"num": "5.12", "responsable": "Operador de la Empresa Subrogada", "actividad": "Genera nota de recolección y entrega al encargado de ropería."}, {"num": "5.13", "responsable": "Operador de la Empresa Subrogada", "actividad": "Deposita los bultos de ropa sucia para su traslado a la empresa."}, {"num": "5.14", "responsable": "UVEH", "actividad": "Supervisa que cada uno de los miembros realice sus funciones adecuadamente."}]'::jsonb,
  '[{"riesgo": "Riesgo de infecciones al paciente y al personal que manipula la ropa hospitalaria.", "barrera": "Supervisión y comunicación continua por parte de los departamentos involucrados."}, {"riesgo": "Desconocimiento y/o omisión de los procesos e instrucciones relacionados con el manejo de ropa.", "barrera": "Realizar capacitación de los procesos e instrucciones que deben aplicarse."}]'::jsonb,
  '[{"nombre": "Proceso de recepción y almacenamiento de ropa limpia hospitalaria.", "codigo": "PR-RO-02"}, {"nombre": "Proceso de almacenamiento y transporte de ropa sucia y contaminada.", "codigo": "PR-RO-01"}, {"nombre": "Instrucción de trabajo para el abastecimiento de ropa limpia hospitalaria.", "codigo": "IT-RO-01"}, {"nombre": "Entrega y recepción de ropa hospitalaria.", "codigo": "FT-RO-01"}, {"nombre": "Instrucción de trabajo para el retiro y clasificación de ropa sucia o contaminada.", "codigo": "IT-JE-27"}, {"nombre": "Horarios y ruta de distribución de ropa.", "codigo": "FT-RO-04"}, {"nombre": "Instrucción de trabajo para desmontaje y sanitización de material y equipo al egreso de paciente de habitación.", "codigo": "IT-JE-45"}, {"nombre": "Norma oficial mexicana NOM-087-SEMARNAT-SSA1-2002 protección ambiental residuos peligrosos biológicos infecciosos, clasificación y especificación de manejo.", "codigo": "NA"}, {"nombre": "Norma oficial epidemiológica mexicana NOM-017-SSA2-1994 para la Vigilancia Epidemiológica.", "codigo": "NA"}, {"nombre": "Ley general de salud art. 17 b i a iii. art. 32, art. 52, constitución política de los estados unidos mexicanos art. 4to.", "codigo": "NA"}]'::jsonb,
  '[{"version": "01", "fecha": "18/04/2022", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "08/02/2024", "descripcion": "Modificación de documento", "realizado": "Dr. Estebán González Díaz", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "03", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Estebán González Díaz"}]'::jsonb,
  '[{"termino": "CODECIAAS", "definicion": "Son las siglas del Comité para la Detección y Control de Infecciones Asociadas a la Atención de la Salud."}]'::jsonb,
