-- PR-UV-22
INSERT INTO document_content (
  document_id, alcance, objetivo,
  material_equipo, desarrollo, gestion_riesgos,
  referencias, control_cambios,
  definiciones, responsabilidades)
SELECT
  (SELECT id FROM documents WHERE code = 'PR-UV-22'),
  'Inicia cuando el departamento de enfermería ejecuta los procesos seguros y termina cuando el departamento de epidemiología supervisa el área.',
  'Implementar procesos seguros que minimicen los riesgos de infecciones asociados a la terapia de reemplazo renal con hemodiálisis.',
  '[]'::jsonb,
  '[{"num": "5.1", "responsable": "Enfermería", "actividad": "El personal operativo correspondiente al área de enfermería ejecuta procesos seguros con el fin de minimizar riesgos de infección. Aplica medidas precautorias para el personal operativo en contacto con pacientes de hemodiálisis (FT-UV-05). EM1"}, {"num": "5.2", "responsable": "Enfermería", "actividad": "Además aplica técnica de desinfección de la máquina de hemodiálisis (IT-JE-22) EM1"}, {"num": "5.3", "responsable": "Enfermería", "actividad": "Realizar (PR-JE-02) comunicación efectiva entre los miembros del equipo de trabajo."}, {"num": "5.4", "responsable": "Enfermería", "actividad": "En caso de paciente con serología positiva se cuenta con la instrucción de Trabajo Para La Atención Y Manejo De Usuario Con Serología Positiva para hepatitis B, C y VIH en Hemodiálisis (IT-JE-19). EM2"}, {"num": "5.5", "responsable": "Enfermería", "actividad": "En cuestión del Manejo de accesos vasculares, se aplica la instrucción de trabajo (IT-JE-20) especifica en catéteres; en cuanto al manejo y cuidado de acceso vascular para hemodiálisis-fístula, se aplica la siguiente instrucción (IT-JE-21). EM2"}, {"num": "5.6", "responsable": "Enfermería", "actividad": "En cuanto al reusó de filtros el departamento de hemodiálisis no realiza esta acción, los filtros son desechables."}, {"num": "5.7", "responsable": "Empresa Subrogada", "actividad": "Toma muestra para análisis microbiológico del agua utilizada en la terapia de reemplazo renal con hemodiálisis. EM2. Apegado siempre a la Norma Oficial Mexicana NOM-092-SSA1-1994, Bienes y Servicios. Métodos para la cuenta de bacterias aerobias en placa."}, {"num": "5.8", "responsable": "Seguridad e Higiene y Medio Ambiente", "actividad": "Realiza monitoreo de la calidad del agua a través de los resultados emitidos por la empresa. EM2. Nota: en caso de detectar niveles fuera de los rangos normales (>1 UFC/mL), se avisa a la empresa subrogada para realizar sanitación. Se realiza sanitización cada último domingo del mes. Supervisa que la empresa cuente con especificaciones de calidad. EM3"}, {"num": "5.9", "responsable": "Epidemiología", "actividad": "Supervisión al departamento apegado a la Norma Oficial Mexicana NOM-003-SSA3-2016: Para la práctica de hemodiálisis a través del formato (FT-UV-04) EM1. En el cual se evalúa que el personal aplica las medidas precautorias correspondientes para el área: Higiene personal, Instalaciones, Evaluación RPBI, Insumos para higiene de manos."}]'::jsonb,
  '[{"riesgo": "Infecciones en los pacientes y colaboradores por mal ejecución de los procesos referentes a la atención de pacientes en el área de Hemodiálisis.", "barrera": "Confirmar que personal del área de hemodiálisis cuente con conocimientos básicos, así como capacidades y aptitudes en el manejo de pacientes con hemodiálisis."}, {"riesgo": "Intoxicación en los pacientes por mala calidad del agua.", "barrera": "Supervisión continúa de los niveles permisibles de cloración de agua (<1 UFC/mL) y corrección en caso de que lo requiera."}, {"riesgo": "Faltante de filtros desechables en el departamento.", "barrera": "Se realiza requisición semanal del material (filtros desechables) para stock del departamento de hemodiálisis, para asegurar que siempre se tenga lo necesario."}]'::jsonb,
  '[{"nombre": "Formato de Medidas precautorias.", "codigo": "FT-UV-05"}, {"nombre": "Instrucción de trabajo de técnica de desinfección de la máquina de hemodiálisis", "codigo": "IT-JE-22"}, {"nombre": "Proceso de comunicación efectiva entre los miembros del equipo de trabajo.", "codigo": "PR-JE-02"}, {"nombre": "Instrucción de trabajo manejo de paciente con serología positiva en hemodiálisis.", "codigo": "IT-JE-19"}, {"nombre": "Instrucción de trabajo manejo y cuidado de acceso vascular para hemodiálisis-catéter.", "codigo": "IT-JE-20"}, {"nombre": "Instrucción de trabajo Manejo y cuidado de acceso vascular para hemodiálisis-fístula.", "codigo": "IT-JE-21"}, {"nombre": "Supervisión de Hemodiálisis.", "codigo": "FT-UV-04"}]'::jsonb,
  '[{"version": "01", "fecha": "06/10/2025", "descripcion": "Alta de documento", "realizado": "Dr. Manuel Cortes Gutiérrez", "aprobado": "Mtra. Ana Cecilia Zarate Bautista"}, {"version": "02", "fecha": "26/09/2025", "descripcion": "Actualización de procedimiento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Esteban González Díaz"}]'::jsonb,
  '[]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Enfermería, Seguridad e higiene y medio ambiente, Empresa Subrogada y Epidemiología."}, {"tipo": "Supervisión", "descripcion": "Dirección Médica."}]'::jsonb
ON CONFLICT (document_id) DO UPDATE SET
  alcance              = EXCLUDED.alcance,
  objetivo             = EXCLUDED.objetivo,
  material_equipo      = EXCLUDED.material_equipo,
  desarrollo           = EXCLUDED.desarrollo,
  gestion_riesgos      = EXCLUDED.gestion_riesgos,
  referencias          = EXCLUDED.referencias,
  control_cambios      = EXCLUDED.control_cambios,
