  '[{"version": "01", "fecha": "26/09/2025", "descripcion": "Alta de documento", "realizado": "Lic. Viridiana López Fajardo", "aprobado": "Dr. Esteban González Díaz"}]'::jsonb,
  '[]'::jsonb,
  '[{"tipo": "Actualización", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}, {"tipo": "Ejecución", "descripcion": "Empresa Subrogada y UVEH."}, {"tipo": "Supervisión", "descripcion": "Unidad de vigilancia epidemiológica hospitalaria (UVEH)."}]'::jsonb
